def fill_existing(apps, schema_editor):
    """Eventos antigos: dia pelo fuso da operação; o que não é ocorrência (ou é de dias passados) fica resolvido."""
    RouteEvent = apps.get_model("core", "RouteEvent")
    tz = ZoneInfo(settings.ADMIN_TIME_ZONE)
    today = django.utils.timezone.now().astimezone(tz).date()
    for event in RouteEvent.objects.all().only("id", "timestamp", "event_type").iterator():
        day = event.timestamp.astimezone(tz).date()
        fields = {"service_date": day}
        if event.event_type not in ("delay", "incident"):
            fields["status"] = "resolved"
        elif day < today:
            fields.update(status="resolved", resolution="Registrada antes do controle de status.")
        RouteEvent.objects.filter(pk=event.pk).update(**fields)


